package io.element.android.libraries.mediaviewer.impl.segmented.prototype

import java.util.Base64

/**
 * Non-sensitive H264 fixture generated by Media3 1.10.1 FragmentedMp4Muxer from one key sample followed by one
 * dependent sample. The exact generator source and output are preserved in the WP08 evidence package.
 */
internal object SegmentedMediaFmp4FixturePrototype {
    val init: ByteArray = decodeBase64(
        "AAAAHGZ0eXBpc29tAAIAAGlzb21pc28ybXA0MQAAAoZtb292AAAAbG12aGQAAAAA5tbw3+bW8N8AACcQAAAAAAABAA",
        "ABAAAAAAAAAAAAAAAAAQAAAAAAAAAAAAAAAAAAAAEAAAAAAAAAAAAAAAAAAEAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA",
        "AAAAAAACAAAB6nRyYWsAAABcdGtoZAAAAAfm1vDf5tbw3wAAAAEAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAQAAAAAA",
        "AAAAAAAAAAAAAAEAAAAAAAAAAAAAAAAAAEAAAAAAEAAAABAAAAAAAYZtZGlhAAAAIG1kaGQAAAAA5tbw3+bW8N8AAV+Q",
        "AAAAAAAAAAAAAAAsaGRscgAAAAAAAAAAdmlkZQAAAAAAAAAAAAAAAFZpZGVvSGFuZGxlAAAAATJtaW5mAAAAFHZtaGQA",
        "AAAAAAAAAAAAAAAAAAAkZGluZgAAABxkcmVmAAAAAAAAAAEAAAAMdXJsIAAAAAEAAADyc3RibAAAAJZzdHNkAAAAAAAA",
        "AAEAAACGYXZjMQAAAAAAAAABAAAAAAAAAAAAAAAAAAAAAAAQABAASAAAAEgAAAAAAAAAAQAAAAAAAAAAAAAAAAAAAAAAAA",
        "AAAAAAAAAAAAAAAAAAABj//wAAACBhdmNDAUIACv/hAAlnQgAK6QFAeyABAARozgbiAAAAEHBhc3AAAQAAAAEAAAAA",
        "ABBzdHRzAAAAAAAAAAAAAAAUc3RzegAAAAAAAAAAAAAAAAAAABBzdHNjAAAAAAAAAAAAAAAQc3RjbwAAAAAAAAAAAAAAEH",
        "N0c3MAAAAAAAAAAAAAAChtdmV4AAAAIHRyZXgAAAAAAAAAAQAAAAEAAAAAAAAAAAAAAAA=",
    )
    val segment: ByteArray = decodeBase64(
        "AAAAZG1vb2YAAAAQbWZoZAAAAAAAAAABAAAATHRyYWYAAAAYdGZoZAAAAAEAAAABAAAAAAAAAqIAAAAsdHJ1bgEABwEA",
        "AAACAAAAbAAAr8gAAAAIAgAAAAAAAAAAAAAHAQEAAAAAABdtZGF0AAAABGUBAgMAAAADQQQF",
    )

    private fun decodeBase64(vararg chunks: String): ByteArray =
        Base64.getDecoder().decode(chunks.joinToString(separator = ""))
}

internal fun aFixtureManifest(
    segments: List<SegmentedMediaResourcePrototype> = listOf(
        aSegment(0, 0L, plainLength = SegmentedMediaFmp4FixturePrototype.segment.size.toLong())
    ),
): SegmentedMediaManifestPrototype {
    val base = aManifest(segments)
    val init = base.init.copy(plainLength = SegmentedMediaFmp4FixturePrototype.init.size.toLong())
    return base.copy(
        codecs = listOf("avc1"),
        init = init,
        totalPlainBytes = init.plainLength + segments.sumOf { it.plainLength },
    )
}

internal fun aRandomAccessProof(
    validatedManifest: ValidatedSegmentedMediaManifestPrototype,
    segmentIndex: Int,
    context: SegmentedMediaReadContextPrototype,
): SegmentedMediaRandomAccessProofPrototype =
    (SegmentedMediaRandomAccessVerifierPrototype.verify(
        validatedManifest = validatedManifest,
        segmentIndex = segmentIndex,
        verifiedInitBytes = SegmentedMediaFmp4FixturePrototype.init.copyOf(),
        verifiedSegmentBytes = SegmentedMediaFmp4FixturePrototype.segment.copyOf(),
        context = context,
        authorizationGate = alwaysAuthorizedGate(context),
    ) as SegmentedMediaRandomAccessResultPrototype.Verified).proof
